/bin/zsh -lc "python3 -c 'import json
x=json.load(open(\"input.json\"))
def reaches(s,t):
 seen={s}; todo=[s]
 while todo:
  v=todo.pop()
  for e in x[\"edges\"]:
   if e[\"source\"]==v and e[\"target\"] not in seen:
    seen.add(e[\"target\"]); todo.append(e[\"target\"])
 return t in seen
reachable=[]; authorized=[]
for p in x[\"probes\"]:
 r=reaches(p[\"source\"],p[\"target\"])
 if r: reachable.append(p[\"id\"])
 if r and p[\"signed\"] is True and p[\"audience\"]==\"control\" and p[\"tenant\"]==p[\"resource_tenant\"] and x[\"now\"]<p[\"expires\"] and p[\"key\"] not in x[\"revoked_keys\"]: authorized.append(p[\"id\"])
print(json.dumps({\"reachable_probes\":sorted(reachable),\"authorized_probes\":sorted(authorized)}))'"

